const search=document.querySelector('#record-search');
search?.addEventListener('input',()=>{const query=search.value.trim().toLocaleLowerCase();let count=0;for(const record of document.querySelectorAll('[data-record]')){record.hidden=!record.textContent.toLocaleLowerCase().includes(query);if(!record.hidden)count++;}for(const group of document.querySelectorAll('.archive-group')){const found=[...group.querySelectorAll('[data-record]')].some(r=>!r.hidden);group.hidden=!found;if(query&&found)group.open=true;}document.querySelector('#record-count').textContent=count+(count===1?' record':' records')+(query?' found':'');});
